+package main
+
+import (
+	"encoding/json"
+	"fmt"
+)
+
+type CaddyHeaders struct {
+	UserAgent      []string `json:"User-Agent"`
+	Referer        []string `json:"Referer"`
+	ContentType    []string `json:"Content-Type"`
+	XForwardedFor  []string `json:"X-Forwarded-For"`
+	AcceptLanguage []string `json:"Accept-Language"`
+}
+
+type CaddyRequest struct {
+	RemoteAddr string       `json:"remote_addr"`
+	Proto      string       `json:"proto"`
+	Method     string       `json:"method"`
+	Host       string       `json:"host"`
+	URI        string       `json:"uri"`
+	Headers    CaddyHeaders `json:"headers"`
+}
+
+type CaddyLogEntry struct {
+	Timestamp   interface{}  `json:"ts"`
+	Request     CaddyRequest `json:"request"`
+	Duration    interface{}  `json:"duration"`
+	Size_       int          `json:"size"`
+	Status_     int          `json:"status"`
+	RespHeaders CaddyHeaders `json:"resp_headers"`
+}
+
+func (l CaddyLogEntry) Referrer() string {
+	if len(l.Request.Headers.Referer) > 0 {
+		return l.Request.Headers.Referer[0]
+	}
+	return ""
+}
+
+func main() {
+	jsonData := `{
+		"request": {
+			"headers": {
+				"Referer": ["https://example.com"]
+			}
+		}
+	}`
+
+	var logEntry CaddyLogEntry
+	err := json.Unmarshal([]byte(jsonData), &logEntry)
+	if err != nil {
+		fmt.Printf("Error: %v\n", err)
+		return
+	}
+
+	fmt.Printf("Referrer: '%s'\n", logEntry.Referrer())
+	fmt.Printf("Headers.Referer: %v\n", logEntry.Request.Headers.Referer)
+}
